INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(92595643, 'Fine', '罚则金', '罰則金', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己把手卡2张丢弃。'),
(51849482, 'Finis Terrae, Tower of the Necroworld', '尸界塔 终尽之地', '屍界塔フィニステラ', 'Effect Monster', 'Zombie', 'WATER', 10, 1000, 2800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有10星怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡被送去墓地的场合，以场上1张表侧表示卡为对象才能发动。这个回合，那张卡不会被效果破坏。'),
(48310593, 'Finite Cards', '无念的手札', '無念の手札', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，双方的手卡限制数量变成3张。'),
(78275321, 'Fire Ant Ascator', '赤蚁 阿斯卡托尔', '赤蟻アスカトル', 'Tuner Monster', 'Insect', 'EARTH', 3, 700, 1300, '①：这张卡被战斗破坏送去墓地时，以自己墓地1只5星怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，这个回合的结束阶段送去墓地。'),
(81109178, 'Fire Cracker', '爆竹鬼', 'ファイヤークラッカー', 'Effect Monster', 'Fiend', 'FIRE', 4, 1700, 200, '「爆竹鬼」的①的效果1回合只能使用1次。 ①：把这张卡从手卡丢弃才能发动。给与对方1000伤害，下次的自己抽卡阶段跳过。这个效果在对方回合也能发动。 ②：只要这张卡在怪兽区域存在，每次对方受到效果伤害给这张卡放置1个指示物。 ③：自己·对方的结束阶段发动。这张卡的指示物全部取除，给与对方那个数量×300伤害。'),
(43061293, 'Fire Darts', '火焰飞镖', 'ファイアーダーツ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己手卡0张的时候才能发动。投掷3次骰子。给与对方基本分那个投掷结果的合计数目×100数值的伤害。'),
(11654067, 'Fire Ejection', '火焰喷射', 'ファイヤー・エジェクション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只炎族怪兽送去墓地。这个效果把「火山」怪兽送去墓地的场合，可以再从以下效果选1个适用。 ●给与对方那个等级×100伤害。 ●在对方场上把1只「炸弹衍生物」（炎族·炎·1星·攻/守1000）特殊召唤。这衍生物被破坏时那个控制者受到500伤害。'),
(88435542, 'Fire Eye', '火眼', 'ファイヤー・アイ', 'Normal Monster', 'Pyro', 'FIRE', 2, 800, 600, '被火炎包围着的眼球。挥动翅膀就能引起火炎之风。'),
(64514892, 'Fire Fighting Daruma Doll', '小法师 灭火达摩', '小法師ヒダルマー', 'Link Monster', 'Beast-Warrior', 'FIRE', NULL, 1500, NULL, '兽族·兽战士族·鸟兽族怪兽2只 ①：这张卡的攻击力上升场上的兽族·兽战士族·鸟兽族怪兽数量×100。 ②：1回合1次，以自己以及对方场上的魔法·陷阱卡各1张为对象才能发动。那些卡破坏。 ③：这张卡战斗破坏对方怪兽时，从自己墓地的怪兽以及除外的自己怪兽之中以1只兽族·兽战士族·鸟兽族怪兽为对象才能发动。那只怪兽加入手卡。'),
(42052439, 'Fire Flint Lady', '取火女郎', 'キリビ・レディ', 'Effect Monster', 'Warrior', 'FIRE', 1, 100, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有战士族怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：把场上的这张卡送去墓地才能发动。从手卡把1只4星以下的战士族怪兽特殊召唤。这个回合，对方不能把这个效果特殊召唤的怪兽作为效果的对象。'),
(93754402, 'Fire Formation - Domei', '炎舞－洞明－', '炎舞－「洞明」', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，以下效果可以适用。 ●等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只兽战士族仪式怪兽仪式召唤。 ②：魔法与陷阱区域的表侧表示的这张卡被送去墓地的场合，以自己墓地1只「炎星」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(19059929, 'Fire Formation - Gyokkou', '炎舞－玉衡－', '炎舞－「玉衝」', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的发动时，选择对方场上盖放的1张魔法·陷阱卡。对方不能对应这张卡的发动把选择的卡发动。只要这张卡在场上存在，选择的卡不能发动。此外，只要这张卡在场上存在，自己场上的兽战士族怪兽的攻击力上升100。'),
(29143457, 'Fire Formation - Ingen', '炎舞－隐元－', '炎舞－「隠元」', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，以下效果可以适用。 ●从自己的手卡·场上把兽战士族融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：魔法与陷阱区域的表侧表示的这张卡被送去墓地的场合，以自己墓地1只「炎星」怪兽为对象才能发动。那只怪兽加入手卡。'),
(33665663, 'Fire Formation - Kaiyo', '炎舞－开阳－', '炎舞－「開陽」', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己场上的兽战士族怪兽向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。此外，只要这张卡在场上存在，自己场上的兽战士族怪兽的攻击力上升300。'),
(70329348, 'Fire Formation - Tenken', '炎舞－天权－', '炎舞－「天権」', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡在主要阶段1才能发动。这张卡的发动时，选择自己场上1只兽战士族怪兽。只在这张卡发动的主要阶段1内，选择的怪兽的效果无效，不受这张卡以外的卡的效果影响。此外，只要这张卡在场上存在，自己场上的兽战士族怪兽的攻击力上升300。'),
(57103969, 'Fire Formation - Tenki', '炎舞－天玑－', '炎舞－「天璣」', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只4星以下的兽战士族怪兽加入手卡。 ②：只要这张卡在魔法与陷阱区域存在，自己场上的兽战士族怪兽的攻击力上升100。'),
(44920699, 'Fire Formation - Tensen', '炎舞－天璇－', '炎舞－「天璇」', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的发动时，选择自己场上1只兽战士族怪兽。选择的怪兽的攻击力直到结束阶段时上升700。此外，只要这张卡在场上存在，自己场上的兽战士族怪兽的攻击力上升300。'),
(10719350, 'Fire Formation - Tensu', '炎舞－天枢－', '炎舞－「天枢」', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只兽战士族怪兽召唤。 ②：只要这张卡在魔法与陷阱区域存在，自己场上的兽战士族怪兽的攻击力上升100。'),
(36499284, 'Fire Formation - Yoko', '炎舞－摇光－', '炎舞－「揺光」', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的发动时可以选择对方场上表侧表示存在的1张卡。那个场合，从自己手卡丢弃1只兽战士族怪兽，选择的卡破坏。此外，只要这张卡在场上存在，自己场上的兽战士族怪兽的攻击力上升100。'),
(66750703, 'Fire Fortress atop Liang Peak', '炎杰的梁山阁', '炎傑の梁山閣', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「炎舞」卡使用。 ①：每次「炎星」怪兽召唤·特殊召唤给这张卡放置1个炎星指示物。 ②：1回合1次，可以把自己场上的炎星指示物的以下数量取除，那个效果发动。 ●2：这个回合，自己的兽战士族怪兽攻击的场合，对方直到伤害步骤结束时卡的效果不能发动。 ●6：从卡组把1只兽战士族怪兽加入手卡。 ●10：从卡组·额外卡组把1只兽战士族怪兽无视召唤条件特殊召唤。'),
(68535320, 'Fire Hand', '火焰手', 'ファイヤー・ハンド', 'Effect Monster', 'Pyro', 'FIRE', 4, 1600, 1000, '①：这张卡被对方破坏送去墓地时，以对方场上1只怪兽为对象才能发动。那只对方怪兽破坏。那之后，可以从卡组把1只「寒冰手」特殊召唤。'),
(18621798, 'Fire King Avatar Arvata', '炎王兽 伽内什', '炎王獣 ガネーシャ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1800, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在怪兽区域存在，怪兽的效果发动时才能发动。那个发动无效，这张卡以外的自己的手卡·场上（表侧表示）1只炎属性怪兽破坏。 ②：这张卡被破坏送去墓地的场合，以「炎王兽 甘尼许」以外的自己墓地1只兽族·兽战士族·鸟兽族的炎属性怪兽为对象才能发动。那只怪兽特殊召唤。那只怪兽的效果无效化，结束阶段破坏。'),
(69000994, 'Fire King Avatar Barong', '炎王兽 巴隆', '炎王獣 バロン', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1800, 200, '①：自己场上的表侧表示的「炎王」怪兽被效果破坏的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡被效果破坏送去墓地的场合，下次的准备阶段发动。从卡组把「炎王兽 巴隆」以外的1张「炎王」卡加入手卡。'),
(54149433, 'Fire King Avatar Garunix', '炎王兽 迦楼多尼克斯', '炎王獣 ガルドニクス', 'Effect Monster', 'Winged Beast', 'FIRE', 3, 700, 1700, '①：自己场上的表侧表示的「炎王」怪兽被效果破坏的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡被对方破坏送去墓地的场合才能发动。从卡组把1只「炎王兽」怪兽特殊召唤。'),
(96594609, 'Fire King Avatar Kirin', '炎王兽 麒麟', '炎王獣 キリン', 'Effect Monster', 'Beast', 'FIRE', 3, 1000, 200, '①：自己场上的表侧表示的「炎王」怪兽被效果破坏的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡被破坏送去墓地的场合才能发动。从卡组把1只炎属性怪兽送去墓地。'),
(38910263, 'Fire King Avatar Rangbali', '炎王兽 哈奴曼', '炎王獣 ハヌマーン', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1600, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的表侧表示的「炎王」怪兽被效果破坏的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡在怪兽区域存在，魔法·陷阱卡的效果发动时才能发动。那个发动无效，这张卡以外的自己的手卡·场上（表侧表示）1只炎属性怪兽破坏。'),
(66413481, 'Fire King Avatar Yaksha', '炎王兽 夜叉', '炎王獣 ヤクシャ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1800, 200, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的表侧表示的「炎王」怪兽被效果破坏的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡被破坏送去墓地的场合才能发动。自己的手卡·场上1张卡破坏。'),
(44455560, 'Fire King Courtier Ulcanix', '炎王妃 乌尔甘尼克斯', '炎王妃 ウルカニクス', 'Effect Monster', 'Winged Beast', 'FIRE', 4, 800, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。这张卡以外的自己的手卡·场上（表侧表示）1只炎属性怪兽破坏，「炎王妃 火神不死鸟」以外的1只兽族·兽战士族·鸟兽族的炎属性怪兽从卡组加入手卡。那之后，可以把这张卡的等级变成和这个效果加入手卡的怪兽相同。 ②：这张卡被破坏送去墓地的场合才能发动。从卡组把1只「炎王神兽 大鹏不死鸟」守备表示特殊召唤。'),
(23015896, 'Fire King High Avatar Garunix', '炎王神兽 迦楼多尼克斯', '炎王神獣 ガルドニクス', 'Effect Monster', 'Winged Beast', 'FIRE', 8, 2700, 1700, '①：这张卡被效果破坏送去墓地的场合，下次的准备阶段发动。这张卡从墓地特殊召唤。 ②：这张卡的①的效果特殊召唤的场合发动。场上的其他怪兽全部破坏。 ③：这张卡被战斗破坏送去墓地时才能发动。从卡组把「炎王神兽 大鹏不死鸟」以外的1只「炎王」怪兽特殊召唤。'),
(2526224, 'Fire King High Avatar Kirin', '炎王神兽 麒麟', '炎王神獣 キリン', 'Effect Monster', 'Beast', 'FIRE', 8, 2400, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，自己·对方的主要阶段才能发动。这张卡以外的自己的手卡·场上（表侧表示）1只炎属性怪兽破坏，这张卡特殊召唤。 ②：这张卡被破坏送去墓地的场合才能发动。从自己的手卡·墓地把「炎王神兽 麒麟」以外的1只「炎王」怪兽特殊召唤。那之后，可以把场上1张卡破坏。'),
(57554544, 'Fire King Island', '炎王的孤岛', '炎王の孤島', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己主要阶段才能发动。自己的手卡·场上1只怪兽破坏，从卡组把1只「炎王」怪兽加入手卡。 ②：自己场上没有怪兽存在的场合才能发动。从手卡把1只鸟兽族·炎属性怪兽特殊召唤。 ③：场地区域的表侧表示的这张卡被送去墓地的场合或者被除外的场合发动。自己场上的怪兽全部破坏。'),
(65305978, 'Fire King Sanctuary', '炎王的圣域', '炎王の聖域', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1张「炎王的孤岛」在自己的场地区域表侧表示放置。 ②：1回合1次，自己的场地区域的卡被效果破坏的场合，可以作为代替把自己的手卡·场上（表侧表示）1只炎属性怪兽破坏。 ③：1回合1次，对方把怪兽特殊召唤的场合才能发动。只用自己场上的「炎王」怪兽为素材进行1只炎属性超量怪兽的超量召唤。'),
(91703676, 'Fire King Sky Burn', '炎王神天烧', '炎王神天焼', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上的「炎王」怪兽和对方场上的卡各相同数量为对象才能发动。那些卡破坏。 ②：自己场上的「炎王」卡被效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(46534755, 'Fire Kraken', '火焰乌贼', 'ファイヤー・クラーケン', 'Normal Monster', 'Aqua', 'FIRE', 4, 1600, 1500, '在水里仍然被火焰熊熊包围着的章鱼。'),
(36006208, 'Fire Lake of the Burning Abyss', '彼岸的沉溺', '彼岸の沈溺', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上2只表侧表示的「彼岸」怪兽送去墓地，以场上最多3张卡为对象才能发动。那些卡破坏。'),
(28363749, 'Fire Opal Head', '火焰蛋白石头领', 'ファイヤーオパールヘッド', 'Pendulum Normal Monster', 'Dinosaur', 'FIRE', 6, 2500, 1000, '正在熊熊燃烧的石脑袋恐龙番长。以其生龙活虎般的动作及火焰来作弄敌人，再用必杀的火蛋白石头龙头锤狠狠招呼对方。'),
(24882256, 'Fire Phoenix @Ignister', '火不死鸟＠伊格尼斯者', 'ファイアフェニックス＠イグニスター', 'Link Monster', 'Cyberse', 'FIRE', NULL, 2300, NULL, '电子界族怪兽2只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡攻击的伤害计算时才能发动。给与对方这张卡的攻击力数值的伤害，那次战斗发生的对对方的战斗伤害变成0。 ②：这张卡被效果破坏的场合才能发动。选对方场上1只怪兽破坏。 ③：连接召唤的这张卡被破坏送去墓地的场合，下次的准备阶段才能发动。这张卡从墓地特殊召唤。'),
(64752646, 'Fire Princess', '爆炎少女', 'ビッグバンガール', 'Effect Monster', 'Pyro', 'FIRE', 4, 1300, 1500, '每次自己的基本分回复，对方受到500分的伤害。'),
(269510, 'Fire Prison', '天火的牢狱', '天火の牢獄', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的龙族怪兽的守备力上升300。 ②：双方不能把连接标记数量比场上的连接怪兽少的连接怪兽连接召唤，连接怪兽以外的怪兽不能攻击。 ③：场上有电子界族连接怪兽2只以上存在的场合，以下效果适用。 ●电子界族怪兽发动的效果无效化。 ●场上的电子界族怪兽不能攻击，不会成为攻击对象，也不会成为效果的对象。'),
(53581214, 'Fire Reaper', '火焰恶魔', 'ファイヤー・デビル', 'Normal Monster', 'Zombie', 'DARK', 2, 700, 500, '手持炎之箭的死神，被其箭击中的话就会变成火人。'),
(42516299, 'Fire Recovery', '火焰回击', 'ファイヤー・バック', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己墓地1只炎属性怪兽为对象才能发动。选自己1张手卡送去墓地，作为对象的怪兽特殊召唤。 ②：把墓地的这张卡除外，以自己的墓地·除外状态的3只炎属性怪兽为对象才能发动。那些怪兽回到卡组。那之后，自己抽1张。'),
(27132350, 'Fire Sorcerer', '火焰巫师', 'ファイヤーソーサラー', 'Flip Effect Monster', 'Spellcaster', 'FIRE', 4, 1000, 1500, '反转：自己的手卡随机选2张除外。对方受到800分的伤害。'),
(53927679, 'Fire Trooper', '火焰骑兵', 'ファイヤー・トルーパー', 'Effect Monster', 'Warrior', 'FIRE', 3, 1000, 1000, '这张卡召唤·反转召唤·特殊召唤成功时，可以把这张卡送去墓地，给与对方基本分1000分伤害。'),
(98596597, 'Fireball Token', '灵魂游荡的墓场', '魂のさまよう墓場', 'Token', 'Pyro', NULL, NULL, NULL, NULL, NULL),
(87473172, 'Firebird', '火炎鸟', '火炎鳥', 'Effect Monster', 'Winged Beast', 'FIRE', 4, 1000, 800, '只要这张卡在场上表侧表示存在，每次自己场上的鸟兽族怪兽被破坏，这张卡攻击力上升500。'),
(373085, 'Firebrand Hymnist', '赞美火', '讃美火', 'Effect Monster', 'Pyro', 'FIRE', 3, 800, 200, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤时才能发动。把对方场上的卡数量的卡从对方卡组上面送去墓地。 ②：这张卡特殊召唤的场合才能发动。把对方场上的卡数量的卡从自己卡组上面送去墓地。'),
(53293545, 'Firegrass', '火炎草', '火炎草', 'Normal Monster', 'Plant', 'EARTH', 2, 700, 600, '在火山附近生存的草。从花内吹出来火焰攻击。'),
(46173679, 'Fires of Doomsday', '终焉之焰', '終焉の焔', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能用这张卡的效果以外把怪兽召唤·反转召唤·特殊召唤。 ①：在自己场上把2只「黑焰衍生物」（恶魔族·暗·1星·攻/守0）守备表示特殊召唤。这衍生物不能为暗属性以外的怪兽的上级召唤而解放。'),
(13846680, 'Firestorm Prominence', '地狱日珥', 'ヘルプロミネンス', 'Effect Monster', 'Reptile', 'FIRE', 7, 2000, 1500, '这张卡被战斗破坏送去墓地时，场上表侧表示存在的炎属性怪兽以外的怪兽全部破坏。'),
(17151328, 'Firestorms Over Atlantis', '旋涡海炎', '渦巻く海炎', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：可以从以下效果选择1个发动。 ●从手卡把1只水属性怪兽丢弃去墓地，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏。 ●手卡1只炎属性怪兽破坏。那之后，自己可以抽1张。 ②：只有对方场上才有怪兽存在的场合，把墓地的这张卡除外，以自己墓地1只7·8星的水·炎属性怪兽为对象才能发动。那只怪兽特殊召唤。'),
(94804055, 'Firewall', '火焰壁', 'ファイヤー・ウォール', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方直接攻击宣言时，可以把自己墓地存在的1只炎族怪兽从游戏中除外，使那只怪兽的攻击无效。每次自己的准备阶段支付500基本分。若没有支付，这张卡破坏。'),
(20455229, 'Firewall Defenser', '防火墙防护者', 'ファイアウォール・ディフェンサー', 'Effect Monster', 'Cyberse', 'DARK', 4, 1200, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡作为电子界族连接怪兽的连接素材送去墓地的场合才能发动（这个效果发动的回合，自己不是电子界族怪兽不能特殊召唤）。从卡组把「防火防守者」以外的1只「防火」怪兽特殊召唤。 ②：自己场上的「防火」怪兽被效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(5043010, 'Firewall Dragon', '防火墙龙', 'ファイアウォール・ドラゴン', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 2500, NULL, '怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：只在这张卡在场上表侧表示存在才有1次，自己·对方回合，以最多有这张卡所互相连接区的怪兽数量的自己·对方的场上·墓地的怪兽为对象才能发动。那些怪兽回到手卡。 ②：这张卡所连接区的怪兽被战斗破坏的场合或者被送去墓地的场合才能发动。从手卡把1只电子界族怪兽特殊召唤。'),
(68934651, 'Firewall Dragon Darkfluid', '防火墙龙・暗流体', 'ファイアウォール・ドラゴン・ダークフルード', 'Link Monster', 'Cyberse', 'DARK', NULL, 3000, NULL, '效果怪兽3只以上 ①：这张卡连接召唤的场合才能发动。自己墓地的电子界族怪兽种类（仪式·融合·同调·超量）数量的指示物给这张卡放置。 ②：这张卡的攻击力在战斗阶段内上升这张卡的指示物数量×2500。 ③：对方把怪兽的效果发动时，把这张卡1个指示物取除才能发动。那个发动无效。这个效果在从这张卡的攻击宣言时到伤害步骤结束时发动的场合，这张卡再1次可以继续攻击。'),
(64211118, 'Firewall Dragon Darkfluid - Neo Tempest Terahertz', '防火墙龙・暗流体－新风暴', 'ファイアウォール・ドラゴン・ダークフルード－ネオテンペスト', 'Link Monster', 'Cyberse', 'DARK', NULL, 3000, NULL, '电子界族怪兽3只以上 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，战斗阶段中对方发动的怪兽的效果无效化。 ②：自己·对方回合可以发动。从卡组·额外卡组把1只电子界族怪兽送去墓地。这张卡也当作和送去墓地的那只怪兽相同属性使用，攻击力上升2500。 ③：这张卡在同1次的战斗阶段中可以向怪兽作出最多有这张卡的属性种类数量的攻击。'),
(21637210, 'Firewall Dragon Singularity', '防火墙龙・奇点', 'ファイアウォール・ドラゴン・シンギュラリティ', 'Link Monster', 'Cyberse', 'DARK', NULL, 3500, NULL, '效果怪兽3只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，以最多有自己的场上·墓地的怪兽种类（仪式·融合·同调·超量）数量的对方的场上·墓地的卡为对象才能发动。那些卡回到手卡。这张卡的攻击力上升回去数量×500。 ②：这张卡所连接区的怪兽被战斗破坏的场合或者被送去墓地的场合，以自己墓地1只电子界族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(21065189, 'Firewall eXceed Dragon', '防火墙超越龙', 'ファイアウォール・X・ドラゴン', 'XYZ Monster', 'Cyberse', 'DARK', 4, 2500, 2000, '4星怪兽×2只以上 ①：超量召唤的这张卡的攻击力上升和这张卡成为连接状态的连接怪兽的连接标记数量×500。 ②：把这张卡2个超量素材取除，以自己墓地1只连接4电子界族连接怪兽为对象才能发动。那只怪兽在要和这张卡成为连接状态的自己场上特殊召唤。这个效果的发动后，直到回合结束时自己不能把怪兽特殊召唤，不能直接攻击。'),
(86605184, 'Firewall Guardian', '防火墙守护者', 'ファイアウォール・ガーディアン', 'Effect Monster', 'Cyberse', 'DARK', 4, 100, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡作为电子界族连接怪兽的连接素材送去墓地的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：自己和对方的连接怪兽之间进行战斗的攻击宣言时把墓地的这张卡除外才能发动。那次攻击无效，那只对方怪兽直到回合结束时原本攻击力变成0，不受自身以外的卡的效果影响。'),
(57940938, 'Firewall Phantom', '防火墙魅影', 'ファイアウォール・ファントム', 'Effect Monster', 'Cyberse', 'DARK', 5, 2000, 1300, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡作为电子界族连接怪兽的连接素材送去墓地的场合才能发动。从卡组把1张「电脑网」魔法·陷阱卡加入手卡。那之后，选自己1张手卡丢弃。 ②：把墓地的这张卡除外才能发动。这个回合的结束阶段，从自己墓地让1只电子界族怪兽回到卡组。'),
(16926971, 'Firewall Saber Dragon', '防火墙军刀龙', 'ファイアウォール・S・ドラゴン', 'Synchro Monster', 'Cyberse', 'DARK', 7, 2300, 2000, '调整＋调整以外的怪兽1只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡同调召唤的场合，以自己的墓地·除外状态的1只电子界族怪兽为对象才能发动。那只怪兽加入手卡。 ②：以自己场上1只其他的电子界族怪兽为对象才能发动。这张卡的等级变成和那只怪兽相同。 ③：这张卡作为连接素材送去墓地的场合才能发动。从卡组把1张「“艾”」魔法卡加入手卡。'),
(27054370, 'Firewing Pegasus', '焰翼天马', 'ファイヤー・ウイング・ペガサス', 'Normal Monster', 'Beast', 'FIRE', 6, 2250, 1800, '展开颜色鲜艳的真红之翼，从天上飞驰而过的天马。'),
(101206080, 'Fireworks Celebration', '火器的祝台', '火器の祝台', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(71407486, 'Fireyarou', '炎之魔神', '炎の魔神', 'Normal Monster', 'Pyro', 'FIRE', 4, 1300, 1000, '被吞没在火中的魔人。运用自如地操纵周围的火焰攻击。'),
(53466722, 'First of the Dragonlords', '始祖的龙王', '始祖の竜王', 'Fusion Monster', 'Dragon', 'DARK', 11, 3700, 3000, '通常怪兽×3 这张卡不用融合召唤不能特殊召唤。这个卡名的③的效果1回合只能使用1次。 ①：「始祖之龙王」在自己场上只能有1张表侧表示存在。 ②：这张卡只要在怪兽区域存在，不会被战斗破坏，不受其他怪兽的效果影响。 ③：只在这张卡表侧表示存在才有1次，魔法·陷阱卡的效果发动时才能发动。场上的魔法·陷阱卡全部破坏。'),
(10817524, 'First of the Dragons', '始祖龙', '始祖竜ワイアーム', 'Fusion Monster', 'Dragon', 'DARK', 9, 2700, 2000, '通常怪兽×2 这张卡不用融合召唤不能特殊召唤。 ①：「始祖龙 古龙」在自己场上只能有1张表侧表示存在。 ②：这张卡只要在怪兽区域存在，不会被和通常怪兽以外的怪兽的战斗破坏，不受这张卡以外的怪兽的效果影响。'),
(12975671, 'First Penguin', '先驱企鹅', 'ファースト・ペンギン', 'Effect Monster', 'Winged Beast', 'WATER', 1, 100, 100, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上没有表侧表示怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤的这张卡当作调整使用。 ②：丢弃1张手卡，把额外卡组1只水属性同调怪兽给对方观看才能发动。比给人观看的怪兽等级低1星并种族相同的1只水属性怪兽从卡组加入手卡。那之后，可以把这张卡变成里侧守备表示。这个回合，自己不是水属性怪兽不能从额外卡组特殊召唤。'),
(19932396, 'First Step Towards Infestation', '侵略的一手', '侵略の一手', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '让自己场上表侧表示存在的1只上级召唤成功的名字带有「侵入魔鬼」的怪兽回到手卡发动。从自己卡组抽1张卡。'),
(33622465, 'First-Aid Squad', '救护部队', '救護部隊', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己墓地1只通常怪兽为对象才能发动。那只怪兽加入手卡。 ②：这张卡在墓地存在，通常怪兽被战斗破坏时才能发动。这张卡变成通常怪兽（战士族·地·3星·攻1200/守400）在怪兽区域守备表示特殊召唤（不当作陷阱卡使用）。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(74271714, 'Fish and Bids', '鱼和喊价', 'フィッシュアンドビッズ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己主要阶段1开始时，把1张手卡除外才能发动。对方可以把2张手卡除外。没除外的场合，自己让以下效果适用。 ●从卡组选2只鱼族怪兽全部送去墓地或全部除外。这个回合，自己不是鱼族怪兽不能特殊召唤。'),
(32703716, 'Fish and Kicks', '鱼和踢出', 'フィッシュアンドキックス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从游戏中除外的自己的鱼族·海龙族·水族怪兽有3只以上的场合，选择场上存在的1张卡发动。选择的卡从游戏中除外。'),
(21507589, 'Fish and Swaps', '鱼和返还', 'フィッシュアンドバックス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '丢弃1张手卡，选择从游戏中除外的2只自己的鱼族·海龙族·水族怪兽才能发动。选择的怪兽加入手卡。'),
(58873391, 'Fish Depth Charge', '鱼弹突击', 'フィッシャーチャージ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的1只鱼族怪兽解放发动。场上1张卡破坏，从自己卡组抽1张卡。'),
(35834119, 'Fish Lamp', '灯鱼', '灯魚', 'Synchro Tuner Monster', 'Fish', 'FIRE', 4, 1200, 400, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡作为同调素材送去墓地的场合才能发动。在自己场上把2只「灯衍生物」（鱼族·炎·2星·攻/守0）特殊召唤。这个回合，自己不是鱼族怪兽不能从额外卡组特殊召唤。 ②：自己场上有鱼族同调怪兽存在的场合，把墓地的这张卡除外，以场上1张卡为对象才能发动。那张卡破坏。'),
(94626050, 'Fish Rain', '鱼雨', 'フィッシュ・レイン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示存在的鱼族·海龙族·水族怪兽从游戏中除外时才能发动。从自己手卡把1只3星以下的鱼族·海龙族·水族怪兽特殊召唤。'),
(22819092, 'Fish Sonar', '鱼群探知机', '魚群探知機', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把7星以下的1只有「海」的卡名记述的怪兽或者水属性通常怪兽加入手卡。场上有「海」存在的场合，可以再从卡组把1只水属性通常怪兽特殊召唤。'),
(62023839, 'Fishborg Archer', '鱼博格－射箭者', 'フィッシュボーグ－アーチャー', 'Tuner Monster', 'Fish', 'WATER', 3, 300, 300, '这个卡名的效果1回合只能使用1次。 ①：这张卡在墓地存在，自己场上没有怪兽存在的场合，从手卡丢弃1只水属性怪兽才能发动。这张卡特殊召唤。这个效果特殊召唤的回合的战斗阶段开始时，水属性怪兽以外的自己场上的怪兽全部破坏。'),
(93369354, 'Fishborg Blaster', '电子鱼人-枪手', 'フィッシュボーグ－ガンナー', 'Tuner Monster', 'Fish', 'WATER', 1, 100, 200, '自己场上有3星以下的水属性怪兽表侧表示存在的场合，丢弃1张手卡才能发动。墓地存在的这张卡在自己场上特殊召唤。把这张卡作为同调素材的场合，其他的同调素材怪兽必须全部是水属性怪兽。'),
(10560119, 'Fishborg Doctor', '鱼博格－诊疗者', 'フィッシュボーグ－ドクター', 'Effect Monster', 'Fish', 'WATER', 4, 400, 400, '「电子鱼人-博士」的②的效果1回合只能使用1次。 ①：自己场上有「电子鱼人」怪兽以外的怪兽存在的场合这张卡破坏。 ②：这张卡在墓地存在，自己场上的怪兽只有「电子鱼人」怪兽的场合，自己主要阶段才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(57420265, 'Fishborg Harpooner', '鱼博格－击叉者', 'フィッシュボーグ－ハープナー', 'Tuner Monster', 'Fish', 'WATER', 4, 400, 400, '这个卡名的①的效果1回合只能使用1次。 ①：把手卡的这张卡和手卡1只水属性怪兽给对方观看才能发动。那2只之内的1只特殊召唤，另1只丢弃。 ②：这张卡作为水属性同调怪兽的同调素材送去墓地的场合才能发动。对方场上1只效果怪兽的效果直到回合结束时无效。'),
(66853752, 'Fishborg Launcher', '鱼博格－发炮者', 'フィッシュボーグ－ランチャー', 'Tuner Monster', 'Fish', 'WATER', 1, 200, 100, '这个卡名的效果1回合只能使用1次，把这张卡作为同调素材的场合，不是水属性怪兽的同调召唤不能使用。 ①：这张卡在墓地存在，「电子鱼人-火箭炮手」以外的自己墓地的怪兽只有水属性怪兽的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(51282878, 'Fishborg Planter', '鱼博格－栽培者', 'フィッシュボーグ－プランター', 'Effect Monster', 'Fish', 'WATER', 2, 200, 200, '只在这张卡在墓地存在才能发动1次。自己卡组最上面的卡送去墓地。送去墓地的卡是水属性怪兽的场合，再把这张卡从墓地特殊召唤。「电子鱼人-栽培者」的效果1回合只能使用1次。'),
(66788016, 'Fissure', '地割', '地割れ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上1只攻击力最低的怪兽破坏。'),
(49181828, 'Fist Armed Dragon', '威慑武装龙', 'スレット・アームド・ドラゴン', 'Effect Monster', 'Dragon', 'WIND', 5, 2400, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在墓地存在的场合，以自己场上1只龙族怪兽为对象才能发动。那只怪兽破坏，这张卡特殊召唤。 ②：丢弃1张手卡，以场上1只攻击力2400以下的怪兽为对象才能发动。那只怪兽破坏。把自己场上的怪兽破坏的场合，可以再把原本等级比那只怪兽高2星的1只龙族怪兽从手卡·卡组特殊召唤。'),
(79868386, 'Fist of Fate', '神拳粉碎', 'ゴッド・ハンド・クラッシャー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。这张卡的发动和效果不会被无效化。 ①：自己场上有原本卡名是「欧贝利斯克之巨神兵」的怪兽存在的场合才能发动。选对方场上1只效果怪兽，把效果无效并破坏。这个回合，这个效果破坏的怪兽以及原本卡名和那只怪兽相同的怪兽的效果无效化。这张卡在自己主要阶段发动的场合，可以再让以下效果适用。 ●对方场上的魔法·陷阱卡全部破坏。'),
(21834870, 'Fists of the Unrivaled Tenyi', '天威无双之拳', '天威無双の拳', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己场上有效果怪兽以外的表侧表示怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效。 ②：盖放的这张卡被对方的效果破坏的场合才能发动。从额外卡组把效果怪兽以外的1只怪兽特殊召唤。'),
(70946699, 'Five Brothers Explosion', '炎虎梁山爆', '炎虎梁山爆', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的发动时，自己回复自己场上的永续魔法·永续陷阱卡数量×500基本分。此外，场上表侧表示存在的这张卡被对方的效果送去墓地的场合，给与对方基本分自己墓地的永续魔法·永续陷阱卡数量×500的数值的伤害。'),
(6309986, 'Five Star Twilight', '闪烁五星', 'ティンクル・ファイブスター', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上的怪兽只有5星怪兽1只的场合，把那只怪兽解放才能发动。从自己的手卡·卡组·墓地选「栗子丸」「栗子团」「栗子圆」「栗子珠」「栗子球」各1只特殊召唤。这个效果特殊召唤的怪兽不能为上级召唤而解放。'),
(99267150, 'Five-Headed Dragon', '五神龙', 'F・G・D', 'Fusion Monster', 'Dragon', 'DARK', 12, 5000, 5000, '龙族怪兽×5 这张卡不用融合召唤不能特殊召唤。 ①：这张卡不会被和暗·地·水·炎·风属性怪兽的战斗破坏。'),
(10669138, 'Five-Headed Link Dragon', '连神龙', 'L・G・D', 'Link Monster', 'Dragon', 'DARK', NULL, 5000, NULL, '怪兽5只 这张卡不用连接召唤不能特殊召唤。 ①：这张卡用暗·地·水·炎·风属性全部为素材作连接召唤成功的场合才能发动。对方场上的卡全部破坏。 ②：场上的这张卡不受其他卡的效果影响，不会被和暗·地·水·炎·风属性怪兽的战斗破坏。 ③：对方结束阶段发动。从自己墓地选5张卡里侧表示除外。不能让5张除外的场合，这张卡送去墓地。'),
(49847524, 'Flame Administrator', '火炎框架管理员', 'フレイム・アドミニスター', 'Link Monster', 'Cyberse', 'FIRE', NULL, 1200, NULL, '电子界族怪兽2只 ①：「炎上框架管理员」在自己场上只能有1只表侧表示存在。 ②：只要这张卡在怪兽区域存在，自己场上的连接怪兽的攻击力上升800。'),
(33034646, 'Flame Armor Ninja', '机甲忍者 火', '機甲忍者フレイム', 'Effect Monster', 'Warrior', 'FIRE', 4, 1700, 1000, '这张卡召唤·反转召唤·特殊召唤成功时，选择自己场上1只名字带有「忍者」的怪兽才能发动。选择的怪兽的等级上升1星。'),
(80794697, 'Flame Bufferlo', '帧缓存火牛', 'フレイム・バッファロー', 'Effect Monster', 'Cyberse', 'FIRE', 3, 1400, 200, '这个卡名的效果1回合只能使用1次。 ①：表侧表示的这张卡从场上离开的场合才能发动。从手卡丢弃1只电子界族怪兽，自己从卡组抽2张。'),
(60862676, 'Flame Cerebrus', '火焰地狱犬', 'フレイム・ケルベロス', 'Normal Monster', 'Pyro', 'FIRE', 6, 2100, 1800, '全身被火包围的魔兽，给予对方地狱之炎的处刑。'),
(42599677, 'Flame Champion', '火焰杀手', 'フレイムキラー', 'Normal Monster', 'Pyro', 'FIRE', 5, 1900, 1300, '使用火焰盾的剑士，之盾能无视任何攻击。'),
(91152455, 'Flame Coating Metalmorph', '钢铁化・钢炎装甲', 'メタル化・鋼炎装甲', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把有「金属化·强化反射装甲」的卡名记述的自己场上1只表侧表示怪兽解放才能把这张卡发动。把有「金属化·强化反射装甲」的卡名记述的1只不能通常召唤的怪兽无视召唤条件从卡组特殊召唤。那之后，可以把这张卡当作持有以下效果的装备卡使用给那只怪兽装备。 ●装备怪兽被战斗·效果破坏的场合，可以作为代替把这张卡送去墓地。'),
(12883044, 'Flame Dancer', '火焰舞者', 'フレイムダンサー', 'Normal Monster', 'Pyro', 'FIRE', 2, 550, 450, '挥舞着燃烧的绳子慢慢接近，不能和他对眼。'),
(58528964, 'Flame Ghost', '火焰幽灵', 'フレイム・ゴースト', 'Fusion Monster', 'Zombie', 'DARK', 3, 1000, 800, '「白骨」＋「岩浆人」'),
(34460851, 'Flame Manipulator', '炎之操纵者', '炎を操る者', 'Normal Monster', 'Spellcaster', 'FIRE', 3, 900, 1000, '游刃有余地穿梭在火海中发动攻击。'),
(58098303, 'Flame Ogre', '火焰食人魔', 'フレイム・オーガ', 'Effect Monster', 'Fiend', 'FIRE', 7, 2400, 1700, '这张卡不能特殊召唤。这张卡的召唤成功时，从自己卡组抽1张卡。'),
(41089128, 'Flame Ruler', '火焰支配者', '炎を支配する者', 'Effect Monster', 'Pyro', 'FIRE', 4, 1500, 1600, '祭品召唤炎属性怪兽的场合，这只怪兽1只作为2只份的祭品使用。'),
(79444933, 'Flame Spirit Ignis', '炎之魔精 伊格尼斯', '炎の魔精イグニス', 'Effect Monster', 'Pyro', 'FIRE', 4, 1500, 1200, '把自己场上表侧表示存在的1只炎属性怪兽解放发动。给与对方基本分自己墓地存在的炎属性怪兽数量×100的数值的伤害。'),
(8080257, 'Flame Swordsdance', '炎之剑舞', '炎の剣舞', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：怪兽特殊召唤的场合才能发动。7星以下的1只「炎之剑士」或者有那个卡名记述的融合怪兽从额外卡组特殊召唤。那之后，可以把场上1只表侧表示怪兽变成里侧守备表示。 ②：对方战斗阶段，把墓地的这张卡除外，把自己场上1只里侧守备表示怪兽解放才能发动。把1只「炎之剑士」或者有那个卡名记述的怪兽从卡组·额外卡组特殊召唤。'),
(45231177, 'Flame Swordsman', '炎之剑士', '炎の剣士', 'Fusion Monster', 'Warrior', 'FIRE', 5, 1800, 1600, '「火焰操纵者」＋「传说的剑豪 正树」'),
(73714736, 'Flame Swordsrealm', '炎之剑域', '炎の剣域', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：在自己的战士族·炎属性怪兽的召唤成功时对方不能把卡的效果发动。 ②：1回合1次，从自己的手卡·场上（表侧表示）把1只怪兽送去墓地才能发动。从额外卡组把1只「炎之剑士」当作融合召唤作特殊召唤。 ③：1回合1次，怪兽的攻击宣言时，以自己场上1只战士族怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时下降1000，那只怪兽以外的自己场上的全部怪兽的攻击力直到回合结束时上升1000。'),
(66499018, 'Flame Tiger', '焰虎', '焔虎', 'Effect Monster', 'Beast', 'FIRE', 4, 1800, NULL, '这张卡在墓地存在，自己场上没有怪兽存在的场合，自己的抽卡阶段时作为进行通常抽卡的代替才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合从游戏中除外。'),
(2830619, 'Flame Viper', '火焰毒蛇', 'フレイム・ヴァイパー', 'Normal Monster', 'Pyro', 'EARTH', 2, 400, 450, '敏捷的行动、从口中吐出火焰的蛇。'),
(25577965, 'Flametongue the Burning Blade', '炎魔刃 火舌', '炎魔刃フレイムタン', 'Link Monster', 'Warrior', 'FIRE', NULL, 1400, NULL, '炎属性怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己场上的表侧表示的魔法·陷阱卡不会被对方的效果破坏。 ②：以自己的除外状态的1只炎属性怪兽为对象才能发动。那只怪兽加入手卡。这个回合，自己不能把这个效果加入手卡的卡以及那些同名卡的效果发动。'),
(54326448, 'Flamvell Archer', '炎狱弓手', 'フレムベル・アーチャー', 'Tuner Monster', 'Pyro', 'FIRE', 3, 1000, 200, '把自己场上表侧表示存在的1只炎族怪兽解放发动。场上存在的名字带有「炎狱」的怪兽的攻击力直到结束阶段时上升800。这个效果1回合只能使用1次。'),
(13761956, 'Flamvell Baby', '炎狱婴儿', 'フレムベル・ベビー', 'Tuner Monster', 'Pyro', 'FIRE', 1, 800, 200, '自己的主要阶段时，把这张卡从手卡送去墓地发动。自己场上表侧表示存在的1只炎属性怪兽的攻击力上升400。'),
(40189917, 'Flamvell Commando', '炎狱死亡枪手', 'フレムベル・デスガンナー', 'Effect Monster', 'Pyro', 'FIRE', 6, 2200, 200, '这张卡不能被特殊召唤。只能通过解放自己场上1只名字带有「炎狱」的怪兽来召唤。1回合1次，可以把自己墓地中存在的1只守备力200的怪兽从游戏中除外，给与对方玩家那只怪兽攻击力数值的伤害。'),
(60718396, 'Flamvell Counter', '炎狱反击', 'フレムベルカウンター', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：魔法·陷阱卡发动时，从自己墓地把1只守备力200的炎属性怪兽除外才能发动。那个发动无效并破坏。'),
(68226653, 'Flamvell Dragnov', '炎狱连射龙', 'フレムベル・ドラグノフ', 'Effect Monster', 'Dragon', 'FIRE', 2, 1100, 200, '这张卡被战斗破坏送去墓地时，给与对方基本分500分伤害。可以把自己墓地存在的这张卡和自己场上表侧表示存在的1只炎属性怪兽从游戏中除外，从自己卡组把1只「炎狱连射龙」加入手卡。'),
(91711547, 'Flamvell Fiend', '炎狱恶魔', 'フレムベル・デビル', 'Effect Monster', 'Fiend', 'FIRE', 5, 2100, 1200, '这张卡给与对方基本分战斗伤害时，给与对方基本分自己墓地存在的炎族怪兽数量×200的数值的伤害。'),
(23297235, 'Flamvell Firedog', '炎狱地狱犬', 'フレムベル・ヘルドッグ', 'Effect Monster', 'Beast', 'FIRE', 4, 1900, 200, '①：这张卡战斗破坏对方怪兽送去墓地时才能发动。从卡组把「炎狱地狱犬」以外的1只守备力200以下的炎属性怪兽特殊召唤。'),
(77372241, 'Flamvell Grunika', '炎狱龙人', 'フレムベル・グルニカ', 'Effect Monster', 'Dragon', 'FIRE', 4, 1700, 200, '这张卡战斗破坏怪兽送去墓地时，给与对方基本分破坏怪兽的等级×200的数值的伤害。'),
(21615956, 'Flamvell Guard', '炎狱护卫者', 'ガード・オブ・フレムベル', 'Normal Tuner Monster', 'Dragon', 'FIRE', 1, 100, 2000, '能运用自如地操纵火焰的炎狱护卫战士。做出灼热防护罩把敌人的攻击反弹回去。'),
(95621257, 'Flamvell Magician', '炎狱魔术师', 'フレムベル・マジカル', 'Tuner Monster', 'Spellcaster', 'FIRE', 4, 1400, 200, '只要自己场上有名字带有「正义盟军」的怪兽存在，这张卡的攻击力上升400。'),
(28332833, 'Flamvell Poun', '炎狱妖猴', 'フレムベル・パウン', 'Effect Monster', 'Pyro', 'FIRE', 1, 200, 200, '这张卡被战斗破坏送去墓地时，可以从自己卡组选择1只守备力200的怪兽加入手卡。'),
(53714009, 'Flamvell Uruquizas', '炎狱魔神', 'フレムベル・ウルキサス', 'Synchro Monster', 'Pyro', 'FIRE', 6, 2100, 400, '调整＋调整以外的怪兽1只以上 这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。每次这张卡给与对方基本分战斗伤害，这张卡的攻击力上升300。'),
(13708425, 'Flare Resonator', '火焰共鸣者', 'フレア・リゾネーター', 'Tuner Monster', 'Fiend', 'FIRE', 3, 300, 1300, '这张卡为同调素材的同调怪兽的攻击力上升300。'),
(96890582, 'Flash Assailant', '秒杀之暗杀者', '秒殺の暗殺者', 'Effect Monster', 'Fiend', 'DARK', 4, 2000, 2000, '这张卡的攻击力·守备力下降自己手卡数量×400的数值。'),
(95372220, 'Flash Charge Dragon', '枪口焰龙', 'マズルフラッシュ・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 2300, NULL, '龙族怪兽2只以上 自己不能在这张卡所连接区让怪兽出现。 ①：1回合1次，这张卡所连接区有怪兽召唤·特殊召唤的场合才能发动。选这张卡所连接区1只怪兽破坏，给与对方500伤害。 ②：这张卡为对象的魔法·陷阱·怪兽的效果发动时，把自己场上1只怪兽解放才能发动。那个发动无效。'),
(17236839, 'Flash Fusion', '瞬间融合', '瞬間融合', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：从自己场上把融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。这个效果融合召唤的怪兽在结束阶段破坏。'),
(17390179, 'Flash Knight', '闪光骑士', '閃光の騎士', 'Pendulum Normal Monster', 'Warrior', 'LIGHT', 4, 1800, 600, '由于神之灵摆而掌握到新力量的骑士。现在是该觉醒过来，解放那股力量了！'),
(31809476, 'Flash of Heraldry', '徽章的明灭', '紋章の明滅', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以对方场上的表侧表示怪兽任意数量为对象才能发动。那些怪兽的卡名当作「不明」使用。 ②：自己结束阶段，这张卡在墓地存在，自己场上有念动力族超量怪兽存在的场合才能发动。这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(39956951, 'Flash of the Forbidden Spell', '封魔一闪', '封魔一閃', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上的怪兽卡区域全部有怪兽存在的场合才能发动。对方场上存在的全部怪兽破坏。'),
(9267769, 'Flashbang', '闪光弹', '閃光弾', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上的怪兽直接攻击成功时才能发动。变成这个回合的结束阶段。'),
(5063379, 'Flavian - Colosseum of the Gladiator Beasts', '剑斗兽的竞技场－弗拉维斯', '剣闘獣の闘技場－フラヴィス', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：丢弃1张手卡才能发动。从卡组把1只「剑斗兽」怪兽加入手卡。 ②：对方怪兽的攻击宣言时才能发动。从卡组把1只「剑斗兽」怪兽特殊召唤。这个效果特殊召唤的怪兽不会被战斗破坏。 ③：这个回合从自己卡组有「剑斗兽」怪兽特殊召唤的场合，结束阶段才能发动。从卡组把1张「剑斗」陷阱卡在自己场上盖放。'),
(39730727, 'Flawless Perfection of the Tenyi', '天威无崩之地', '天威無崩の地', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，效果怪兽以外的场上的表侧表示怪兽不受怪兽的效果影响。 ②：1回合1次，对方把效果怪兽特殊召唤的场合，若自己场上有效果怪兽以外的怪兽存在则能发动。自己抽2张。'),
(54399598, 'Fleeting Flower of the Magician', '魔术师之瞬绽花', NULL, 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '以对方场上1张表侧表示的魔法·陷阱卡，或者自己场上1张魔法·陷阱卡为对象；那张卡破坏，以自己场上的卡为对象来发动的场合，可以再从以下效果选1个适用。 ●从自己墓地把1只怪兽当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。 ●从自己墓地把1张装备·永续魔法卡加入手卡。 「魔术师之瞬绽花」在1回合只能发动1张。'),
(61807040, 'Flelf', '挥精灵', 'フルエルフ', 'Effect Monster', 'Spellcaster', 'WIND', 2, 800, 1300, '1回合1次，把手卡1只怪兽给对方观看才能发动。直到结束阶段时，这张卡的等级上升给人观看的怪兽的等级数值。'),
(19642774, 'Fleur Synchron', '花之同步士', 'フルール・シンクロン', 'Tuner Monster', 'Machine', 'LIGHT', 2, 400, 200, '①：这张卡作为同调素材送去墓地的场合才能发动。从手卡把1只2星以下的怪兽特殊召唤。'),
(10204849, 'Fleuret de Fleur', '鲜花之花剑', 'フルール・ド・フルーレ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：以自己墓地1只2星以下的怪兽为对象才能把这张卡发动。那只怪兽效果无效特殊召唤，把这张卡装备。这张卡从场上离开时那只怪兽破坏。 ②：装备怪兽的攻击力上升700。 ③：这张卡从魔法与陷阱区域送去墓地的场合才能发动。选自己场上1只同调怪兽把这张卡装备。'),
(209710, 'Flick Clown', '滑动触控王冠人', 'フリック・クラウン', 'Effect Monster', 'Cyberse', 'DARK', 4, 1000, 1400, '这个卡名的效果1回合只能使用1次。 ①：自己场上有这张卡以外的电子界族怪兽2只以上存在，自己手卡是0张的场合，支付1000基本分才能发动。自己从卡组抽1张。'),
(300202008, 'Flight of the Harpies', NULL, NULL, 'Skill Card', 'Mai', NULL, NULL, NULL, NULL, NULL),
(75560629, 'Flint', '打火石', 'フリント', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这张卡装备的怪兽，不能改变表示形式和攻击宣言，攻击力下降300。装备怪兽破坏的场合，选择场上1只怪兽，把这张卡装备在那只怪兽上。'),
(84778110, 'Flint Cragger', '火石岩壁龙', 'フリント・クラッガー', 'Effect Monster', 'Rock', 'EARTH', 3, 800, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。选自己1张手卡丢弃，从额外卡组把1只「化石」融合怪兽送去墓地。 ②：把场上的这张卡送去墓地才能发动。给与对方500伤害。自己墓地有「化石融合」存在的场合，可以再选除外的自己1张「化石融合」或者1张有那个卡名记述的卡回到墓地。'),
(83812099, 'Flint Lock', '火石战机', 'フリントロック', 'Effect Monster', 'Machine', 'LIGHT', 4, 1500, 800, '场上有表侧表示的「打火石」存在的场合，可以给这张卡装备。这个效果1回合只能使用1次。此外，可以把这张卡装备的1张「打火石」给场上存在的1只表侧表示怪兽装备。这张卡可以装备的「打火石」最多1张。只要这张卡有「打火石」装备，这张卡不受「打火石」的效果影响，并且不会被战斗破坏。'),
(16437822, 'Flint Missile', '火石打击', 'フリント・アタック', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把有「打火石」装备的1只怪兽破坏。发动后这张卡被送去墓地时，这张卡可以回到卡组。'),
(81278754, 'Flip Flop Frog', '里青蛙', '裏ガエル', 'Effect Monster', 'Aqua', 'WATER', 2, 500, 200, '这张卡1回合只有1次可以变成里侧守备表示。这张卡反转时，可以让最多有自己场上表侧表示存在的名字带有「青蛙」的怪兽数量的对方场上存在的怪兽回到持有者手卡。'),
(32176662, 'Flip Frozen', '触发器冻结妖', 'フリップ・フローズン', 'Effect Monster', 'Cyberse', 'WATER', 1, 500, 500, '①：这张卡被送去墓地的场合才能发动。对方场上的攻击表示怪兽全部变成守备表示。'),
(11024707, 'Flipping Feline', '回猫', '回猫', 'Flip Effect Monster', 'Beast', 'EARTH', 2, 200, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡从手卡·卡组送去墓地的场合才能发动。这张卡里侧守备表示特殊召唤。 ②：反转过的这张卡在怪兽区域存在的状态，怪兽从手卡·卡组送去自己墓地的场合，以那之内的1只为对象才能发动。那只怪兽里侧守备表示特殊召唤。'),
(50134646, 'Flock Together', '熙攘攒动绣眼鸟', '目白圧し', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个，若非怪兽区域的卡和魔法与陷阱区域的表侧表示的怪兽卡合计10张以上存在的场合则不能发动。 ①：从卡组把1只怪兽当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。 ②：把墓地的这张卡除外才能发动。从卡组把1只怪兽当作永续陷阱卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(9400127, 'Flogos, the Ogdoadic Boundless', '溟界之漠－胡洛激', '溟界の漠－フロギ', 'Effect Monster', 'Reptile', 'LIGHT', 4, 1800, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡从场上送去墓地的场合或者从墓地的特殊召唤成功的场合，以对方场上1只表侧表示怪兽和持有那只怪兽的攻击力以上的攻击力的对方墓地1只怪兽为对象才能发动。作为对象的墓地的怪兽在对方场上特殊召唤，作为对象的对方场上的怪兽送去墓地。 ②：这张卡在墓地存在的场合，把1张手卡送去墓地才能发动。这张卡加入手卡。'),
(69599136, 'Floodgate Trap Hole', '无底落穴', '底なし落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方对怪兽的召唤·反转召唤·特殊召唤成功时才能发动。那些怪兽变成里侧守备表示。这个效果变成里侧守备表示的怪兽不能把表示形式变更。'),
(54334420, 'Floowandereeze & Eglen', '随风飘飘游×鹰仔', 'ふわんだりぃず×いぐるん', 'Effect Monster', 'Winged Beast', 'WIND', 1, 800, 1000, '这个卡名的①③的效果1回合各能使用1次，这些效果发动的回合，自己不能把怪兽特殊召唤。 ①：这张卡召唤成功的场合才能发动。从卡组把1只7星以上的鸟兽族怪兽加入手卡。那之后，可以把1只鸟兽族怪兽召唤。 ②：表侧表示的这张卡从场上离开的场合除外。 ③：这张卡除外中的状态，自己场上有鸟兽族怪兽召唤的场合才能发动。这张卡加入手卡。'),
(80611581, 'Floowandereeze & Empen', '随风飘飘游×帝企', 'ふわんだりぃず×えんぺん', 'Effect Monster', 'Winged Beast', 'WIND', 10, 2700, 1000, '①：这张卡上级召唤成功的场合才能发动。从卡组把1张「随风旅鸟」魔法·陷阱卡加入手卡。那之后，可以把1只怪兽召唤。 ②：只要上级召唤的这张卡在怪兽区域存在，对方场上的特殊召唤的攻击表示怪兽不能把效果发动。 ③：这张卡和对方怪兽进行战斗的伤害计算时1次，把1张手卡除外才能发动。那只对方怪兽的攻击力·守备力直到回合结束时变成一半。'),
(18940725, 'Floowandereeze & Robina', '随风飘飘游×知更', 'ふわんだりぃず×ろびーな', 'Effect Monster', 'Winged Beast', 'WATER', 1, 600, 1200, '这个卡名的①③的效果1回合各能使用1次，这些效果发动的回合，自己不能把怪兽特殊召唤。 ①：这张卡召唤成功的场合才能发动。从卡组把1只4星以下的鸟兽族怪兽加入手卡。那之后，可以把1只鸟兽族怪兽召唤。 ②：表侧表示的这张卡从场上离开的场合除外。 ③：这张卡除外中的状态，自己场上有鸟兽族怪兽召唤的场合才能发动。这张卡加入手卡。'),
(53212882, 'Floowandereeze & Snowl', '随风飘飘游×雪喵', 'ふわんだりぃず×すのーる', 'Effect Monster', 'Winged Beast', 'WATER', 10, 2900, 800, '①：上级召唤的这张卡存在的场合，1回合1次，可以发动。这个回合自己可以进行通常召唤最多3次。 ②：只要上级召唤的这张卡在怪兽区域存在，自己怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ③：对方回合1次，把1张手卡除外才能发动。对方场上的特殊召唤的怪兽全部变成里侧守备表示。'),
(80433039, 'Floowandereeze & Stri', '随风飘飘游×鸵鸵', 'ふわんだりぃず×すとりー', 'Effect Monster', 'Winged Beast', 'WATER', 1, 700, 1100, '这个卡名的①③的效果1回合各能使用1次，这些效果发动的回合，自己不能把怪兽特殊召唤。 ①：这张卡召唤成功的场合，以自己或者对方的墓地1张卡为对象才能发动。那张卡除外。那之后，可以把1只鸟兽族怪兽召唤。 ②：表侧表示的这张卡从场上离开的场合除外。 ③：这张卡除外中的状态，自己场上有鸟兽族怪兽召唤的场合才能发动。这张卡加入手卡。'),
(17827173, 'Floowandereeze & Toccan', '随风飘飘游×大嘴', 'ふわんだりぃず×とっかん', 'Effect Monster', 'Winged Beast', 'WIND', 1, 500, 1300, '这个卡名的①③的效果1回合各能使用1次，这些效果发动的回合，自己不能把怪兽特殊召唤。 ①：这张卡召唤成功的场合，以除外的1张自己的「随风旅鸟」卡为对象才能发动。那张卡加入手卡。那之后，可以把1只鸟兽族怪兽召唤。 ②：表侧表示的这张卡从场上离开的场合除外。 ③：这张卡除外中的状态，自己场上有鸟兽族怪兽召唤的场合才能发动。这张卡加入手卡。'),
(69087397, 'Floowandereeze and the Advent of Adventure', '随风飘飘游与旅行准备', 'ふわんだりぃずと旅じたく', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡以及自己场上的表侧表示怪兽之中把1只鸟兽族怪兽除外才能发动。从卡组把1只「随风旅鸟」怪兽或者1张「随风旅鸟」场地魔法卡加入手卡。那之后，自己回复500基本分。'),
(41215808, 'Floowandereeze and the Dreaming Town', '随风飘飘游与梦之乡', 'ふわんだりぃずと夢の町', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己·对方的主要阶段才能发动。把1只4星以下的鸟兽族怪兽召唤。 ②：这张卡在墓地存在的状态，自己对7星以上的怪兽的上级召唤成功的场合，把这张卡除外才能发动。对方场上的怪兽全部变成里侧守备表示。'),
(28126717, 'Floowandereeze and the Magnificent Map', '随风飘飘游与谜之地图', 'ふわんだりぃずと謎の地図', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把1只1星「随风旅鸟」怪兽给对方观看，和给人观看的怪兽卡名不同的1张「随风旅鸟」卡从卡组除外。那之后，给人观看的怪兽召唤。 ②：对方对怪兽的召唤成功的场合才能发动。自己把1只「随风旅鸟」怪兽召唤。'),
(77610503, 'Floowandereeze and the Scary Sea', '随风飘飘游与恐怖的海', 'ふわんだりぃずと怖い海', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有上级召唤的表侧表示怪兽存在，没有特殊召唤的怪兽存在的场合，对方把怪兽特殊召唤之际才能发动。那次特殊召唤无效，那些怪兽回到持有者手卡。这个回合，对方不能把怪兽特殊召唤，可以进行通常召唤最多3次。'),
(55521751, 'Floowandereeze and the Unexplored Winds', '随风飘飘游与未知之风', 'ふわんだりぃずと未知の風', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，自己作需要怪兽2只解放的上级召唤的场合，可以不把怪兽2只解放而把自己场上1只怪兽和对方场上1张卡送去墓地来上级召唤。 ②：自己主要阶段才能发动。手卡最多2只鸟兽族怪兽给对方观看，用喜欢的顺序回到卡组最下面。那之后，自己从卡组抽出回去的数量。'),
(32887445, 'Flourishing Frolic', '繁华的花笑', '繁華の花笑み', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己墓地的「繁华的花笑」的数量＋3张从自己卡组上面翻开。那之中有3种类（怪兽·魔法·陷阱）的卡的场合，选那之内的1张加入手卡，剩下的卡送去墓地。没有的场合，翻开的卡全部回到卡组。'),
(3966653, 'Flower Cardian Boardefly', '花札卫-猪鹿蝶-', '花札衛－猪鹿蝶－', 'Synchro Monster', 'Warrior', 'DARK', 6, 2000, 2000, '调整＋调整以外的怪兽2只 ①：只要这张卡在怪兽区域存在，自己的「花札卫」怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ②：1回合1次，把自己墓地1只「花札卫」怪兽除外才能发动。直到下次的对方回合结束时，对方不能把墓地的卡的效果发动，不能从墓地把怪兽特殊召唤。'),
(30382214, 'Flower Cardian Cherry Blossom', '花札卫-樱-', '花札衛－桜－', 'Effect Monster', 'Warrior', 'DARK', 3, 100, 100, '①：自己场上有2星以下的「花札卫」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是「花札卫」怪兽不能召唤·特殊召唤。 ②：1回合1次，把自己场上1只「花札卫」怪兽解放才能发动。自己从卡组抽1张，给双方确认。那是「花札卫」怪兽的场合，可以从卡组把「花札卫-樱-」以外的1只「花札卫」怪兽加入手卡或特殊召唤。不是的场合，那张卡送去墓地。'),
(5489987, 'Flower Cardian Cherry Blossom with Curtain', '花札卫-樱上幕帘-', '花札衛－桜に幕－', 'Effect Monster', 'Warrior', 'DARK', 3, 2000, 2000, '这张卡不能通常召唤。这张卡的①的效果可以特殊召唤。 ①：把手卡的这张卡给对方观看才能发动。自己从卡组抽1张，给双方确认。那是「花札卫」怪兽的场合，这张卡特殊召唤。不是的场合，那张卡和这张卡送去墓地。 ②：自己的「花札卫」怪兽和对方怪兽进行战斗的从伤害步骤开始时到伤害计算前，把这张卡从手卡丢弃才能发动。那只进行战斗的自己怪兽的攻击力直到回合结束时上升1000。'),
(94388754, 'Flower Cardian Clover with Boar', '花札卫-萩间猪-', '花札衛－萩に猪－', 'Effect Monster', 'Warrior', 'DARK', 7, 1000, 1000, '这张卡不能通常召唤。把「花札卫-萩间猪-」以外的自己场上1只「花札卫」怪兽解放的场合可以特殊召唤。 ①：这张卡特殊召唤成功的场合发动。自己从卡组抽1张，给双方确认。那是「花札卫」怪兽的场合，可以选对方场上1只怪兽破坏。不是的场合，那张卡送去墓地。'),
(87460579, 'Flower Cardian Lightflare', '花札卫-五光-', '花札衛－五光－', 'Synchro Monster', 'Warrior', 'DARK', 10, 5000, NULL, '调整＋调整以外的怪兽4只 ①：1回合1次，对方把魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ②：自己的「花札卫」怪兽和对方怪兽进行战斗的场合，只在战斗阶段内那只对方怪兽的效果无效化。 ③：同调召唤的这张卡被战斗破坏的场合或者因对方的效果从场上离开的场合才能发动。从额外卡组把「花札卫-五光-」以外的1只「花札卫」同调怪兽特殊召唤。'),
(42291297, 'Flower Cardian Lightshower', '花札卫-雨四光-', '花札衛－雨四光－', 'Synchro Monster', 'Warrior', 'DARK', 8, 3000, 3000, '调整＋调整以外的怪兽3只 ①：只要这张卡在怪兽区域存在，自己场上的「花札卫」怪兽不会被效果破坏，不会成为对方的效果的对象。 ②：对方抽卡阶段对方通常抽卡的场合发动。给与对方1500伤害。 ③：对方结束阶段从以下效果选择1个发动。 ●下次的自己回合的抽卡阶段跳过。 ●这张卡的效果直到下次的对方准备阶段无效。'),
(21772453, 'Flower Cardian Maple with Deer', '花札卫-枫间鹿-', '花札衛－紅葉に鹿－', 'Effect Monster', 'Warrior', 'DARK', 10, 1000, 1000, '这张卡不能通常召唤。把「花札卫-枫间鹿-」以外的自己场上1只「花札卫」怪兽解放的场合可以特殊召唤。 ①：这张卡特殊召唤成功的场合发动。自己从卡组抽1张，给双方确认。那是「花札卫」怪兽的场合，可以选对方场上1张魔法·陷阱卡破坏。不是的场合，那张卡送去墓地。'),
(33541430, 'Flower Cardian Moonflowerviewing', '花札卫-月花见-', '花札衛－月花見－', 'Synchro Tuner Monster', 'Warrior', 'DARK', 6, 2000, 2000, '调整＋调整以外的怪兽2只 ①：1回合1次，自己主要阶段才能发动。自己从卡组抽1张，给双方确认。那是「花札卫」怪兽的场合，可以把那只怪兽无视召唤条件特殊召唤。这个效果特殊召唤的怪兽在这个回合可以直接攻击。这个效果发动的场合，下次的自己回合的抽卡阶段跳过。 ②：把场上的这张卡作为同调素材的场合，可以把包含这张卡的全部同调素材怪兽当作2星怪兽使用。'),
(80630522, 'Flower Cardian Paulownia', '花札卫-桐-', '花札衛－桐－', 'Effect Monster', 'Warrior', 'DARK', 12, 100, 100, '①：自己场上有11星以下的「花札卫」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是「花札卫」怪兽不能召唤·特殊召唤。 ②：这张卡被选择作为攻击对象时才能发动。那次攻击无效，战斗阶段结束。那之后，自己从卡组抽1张。'),
(16802689, 'Flower Cardian Paulownia with Phoenix', '花札卫-桐上凤凰-', '花札衛－桐に鳳凰－', 'Effect Monster', 'Warrior', 'DARK', 12, 2000, 2000, '这张卡不能通常召唤。把「花札卫-桐上凤凰-」以外的自己场上1只12星「花札卫」怪兽解放的场合可以特殊召唤。 ①：这张卡特殊召唤成功的场合发动。自己从卡组抽1张，给双方确认。那是「花札卫」怪兽的场合，可以把那只怪兽特殊召唤。不是的场合，那张卡送去墓地。 ②：1回合1次，这张卡给与对方战斗伤害时才能发动。自己从卡组抽1张。'),
(57261568, 'Flower Cardian Peony with Butterfly', '花札卫-牡丹上蝴蝶-', '花札衛－牡丹に蝶－', 'Tuner Monster', 'Warrior', 'DARK', 6, 1000, 1000, '这张卡不能通常召唤。把「花札卫-牡丹上蝴蝶-」以外的自己场上1只「花札卫」怪兽解放的场合可以特殊召唤。 ①：这张卡特殊召唤成功的场合发动。自己从卡组抽1张，给双方确认。那是「花札卫」怪兽的场合，从对方卡组上面把3张卡确认，用喜欢的顺序回到卡组上面或下面。不是的场合，那张卡送去墓地。 ②：把场上的这张卡作为同调素材的场合，可以把包含这张卡的全部同调素材怪兽当作2星怪兽使用。'),
(81752019, 'Flower Cardian Pine', '花札卫-松-', '花札衛－松－', 'Effect Monster', 'Warrior', 'DARK', 1, 100, 100, '「花札卫-松-」的①的效果1回合只能使用1次。 ①：这张卡召唤成功的场合发动。自己从卡组抽1张，给双方确认。那是「花札卫」怪兽以外的场合，那张卡送去墓地。 ②：这张卡被战斗或者对方的效果破坏送去墓地的场合才能发动。自己从卡组抽1张。'),
(16024176, 'Flower Cardian Pine with Crane', '花札卫-松上鹤-', '花札衛－松に鶴－', 'Effect Monster', 'Warrior', 'DARK', 1, 2000, 2000, '这张卡不能通常召唤。把「花札卫-松上鹤-」以外的自己场上1只1星「花札卫」怪兽解放的场合可以特殊召唤。 ①：这张卡特殊召唤成功的场合发动。自己从卡组抽1张，给双方确认。那是「花札卫」怪兽的场合，可以把那只怪兽特殊召唤。不是的场合，那张卡送去墓地。 ②：这张卡进行战斗的战斗阶段结束时才能发动。自己从卡组抽1张。'),
(54135423, 'Flower Cardian Willow', '花札卫-柳-', '花札衛－柳－', 'Effect Monster', 'Warrior', 'DARK', 11, 100, 100, '①：自己场上有10星以下的「花札卫」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是「花札卫」怪兽不能召唤·特殊召唤。 ②：1回合1次，以自己墓地1只「花札卫」怪兽为对象才能发动。那只怪兽加入卡组洗切。那之后，自己从卡组抽1张。'),
(89818984, 'Flower Cardian Willow with Calligrapher', '花札卫-柳间小野道风-', '花札衛－柳に小野道風－', 'Tuner Monster', 'Warrior', 'DARK', 11, 2000, 2000, '这张卡不能通常召唤。把「花札卫-柳间小野道风-」以外的自己场上1只11星「花札卫」怪兽解放的场合可以特殊召唤。 ①：这张卡特殊召唤成功的场合发动。自己从卡组抽1张，给双方确认。那是「花札卫」怪兽的场合，可以把那只怪兽特殊召唤。不是的场合，那张卡送去墓地。 ②：把场上的这张卡作为同调素材的场合，可以把包含这张卡的全部同调素材怪兽当作2星怪兽使用。'),
(17141718, 'Flower Cardian Zebra Grass', '花札卫-芒-', '花札衛－芒－', 'Effect Monster', 'Warrior', 'DARK', 8, 100, 100, '①：自己场上有7星以下的「花札卫」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是「花札卫」怪兽不能召唤·特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。手卡的「花札卫」怪兽任意数量给对方观看，回到卡组洗切。那之后，自己从卡组抽出回到卡组的数量。'),
(43413875, 'Flower Cardian Zebra Grass with Moon', '花札卫-芒上月-', '花札衛－芒に月－', 'Effect Monster', 'Warrior', 'DARK', 8, 2000, 2000, '这张卡不能通常召唤。把「花札卫-芒上月-」以外的自己场上1只8星「花札卫」怪兽解放的场合可以特殊召唤。 ①：这张卡特殊召唤成功的场合发动。自己从卡组抽1张，给双方确认。那是「花札卫」怪兽的场合，可以把那只怪兽特殊召唤。不是的场合，那张卡送去墓地。 ②：1回合1次，这张卡战斗破坏对方怪兽时才能发动。自己从卡组抽1张。'),
(78785392, 'Flower Gathering', '花合', '花合わせ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「花合」在1回合只能发动1张，这张卡发动的回合，自己不是「花札卫」怪兽不能召唤·特殊召唤。 ①：从卡组把4只攻击力100的「花札卫」怪兽攻击表示特殊召唤（同名卡最多1张）。这个效果特殊召唤的怪兽的效果无效化，不能为上级召唤而解放。'),
(30786387, 'Flower Stacking', '花积', '花積み', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「花积」的②的效果1回合只能使用1次。 ①：从卡组选「花札卫」怪兽3种类，用喜欢的顺序回到卡组上面。 ②：把墓地的这张卡除外，以自己墓地1只「花札卫」怪兽为对象才能发动。那只怪兽加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(95952802, 'Flower Wolf', '花狼', 'フラワー・ウルフ', 'Fusion Monster', 'Beast', 'EARTH', 5, 1800, 1400, '「银牙狼」＋「魔界之棘」'),
(45010690, 'Flowerbot', '鲜花机器人', 'フラボット', 'Effect Monster', 'Plant', 'EARTH', 3, 1500, 800, '①：这张卡被送去墓地的场合发动。自己从卡组抽1张。那之后，1张手卡回到持有者卡组最上面。'),
(10851853, 'Flowerdino', '恐花鳄', 'フラワーダイノ', 'Effect Monster', 'Dinosaur', 'EARTH', 4, 2000, NULL, '这张卡不能通常召唤，用这张卡的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：自己把陷阱卡的效果发动的场合或者对方把魔法卡的效果发动的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡被送去墓地的场合，从除外的自己以及对方的魔法·陷阱卡之中以合计3张为对象才能发动。那些卡用喜欢的顺序回到持有者卡组下面。那之后，自己从卡组抽1张。'),
(83793721, 'Flowering Etoile the Melodious Magnificat', '幻奏华歌神 绚烂舞星', '幻奏の華歌神フラワリング・エトワール', 'Fusion Monster', 'Fairy', 'LIGHT', 8, 2800, 1500, '「幻奏的音姬」怪兽＋「幻奏」怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：自己·对方回合可以发动。自己场上的「幻奏」怪兽任意数量直到结束阶段除外。那之后，可以让最多有这个效果除外的怪兽数量的对方场上的表侧表示卡回到手卡。 ②：融合召唤的表侧表示的这张卡因对方从场上离开的场合才能发动。从卡组·额外卡组把「幻奏的华歌神 花开之埃图瓦勒」以外的1只「幻奏」怪兽特殊召唤。'),
(15341822, 'Fluff Token', '蒲公英狮', 'ダンディライオン', 'Token', 'Plant', NULL, NULL, NULL, NULL, NULL),
(45215225, 'Fluffal Angel', '毛绒动物天使', 'ファーニマル・エンジェル', 'Pendulum Effect Monster', 'Fairy', 'LIGHT', 2, 600, 1200, '这个卡名的怪兽效果1回合只能使用1次。 ①：把这张卡解放，以自己墓地1只「魔玩具」融合怪兽为对象才能发动。选1张手卡丢弃，作为对象的怪兽特殊召唤。'),
(3841833, 'Fluffal Bear', '绒毛动物・熊', 'ファーニマル・ベア', 'Effect Monster', 'Fairy', 'EARTH', 3, 1200, 800, '「毛绒动物·熊」的①②的效果1回合只能有1次使用其中任意1个。 ①：把手卡的这张卡送去墓地才能发动。从卡组选1张「玩具罐」在自己的魔法与陷阱区域盖放。 ②：把这张卡解放，以自己墓地1张「融合」为对象才能发动。那张卡加入手卡。'),
(2729285, 'Fluffal Cat', '绒毛动物・猫', 'ファーニマル・キャット', 'Effect Monster', 'Fairy', 'EARTH', 1, 700, 300, '「毛绒动物·猫」的效果1回合只能使用1次。 ①：这张卡成为融合召唤的素材送去墓地的场合，以自己墓地1张「融合」为对象才能发动。那张卡加入手卡。'),
(9298235, 'Fluffal Crane', '毛绒动物娃娃机', 'ファーニマル・クレーン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的表侧表示的「毛绒动物」怪兽被对方怪兽的攻击或者对方的效果破坏送去自己墓地时，以破坏的那1只自己怪兽为对象才能发动。那只怪兽加入手卡，自己从卡组抽1张。'),
(39246582, 'Fluffal Dog', '绒毛动物・狗', 'ファーニマル・ドッグ', 'Effect Monster', 'Fairy', 'EARTH', 4, 1700, 1000, '「毛绒动物·狗」的效果1回合只能使用1次。 ①：这张卡从手卡的召唤·特殊召唤成功时才能发动。从卡组把1只「锋利小鬼·剪刀」或者1只「毛绒动物·狗」以外的「毛绒动物」怪兽加入手卡。'),
(82896870, 'Fluffal Dolphin', '绒毛动物・海豚', 'ファーニマル・ドルフィン', 'Effect Monster', 'Fairy', 'WATER', 4, 1600, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1张「玩具罐」为对象才能发动。那张卡在自己场上盖放，从卡组把1只「锋利小鬼·剪刀」或者1只「毛绒动物」怪兽送去墓地。 ②：这张卡成为融合召唤的素材送去墓地的场合才能发动。从自己墓地的卡以及除外的自己的卡之中选1张「融合」魔法卡回到卡组。'),
(66457138, 'Fluffal Leo', '毛绒动物·狮子', 'ファーニマル・ライオ', 'Effect Monster', 'Fairy', 'EARTH', 4, 1600, 1200, '①：这张卡的攻击宣言时发动。这张卡的攻击力直到战斗阶段结束时上升500。'),
(6142488, 'Fluffal Mouse', '毛绒动物·鼠', 'ファーニマル・マウス', 'Effect Monster', 'Fairy', 'EARTH', 1, 100, 100, '这张卡的效果发动的回合，自己不是「魔玩具」怪兽不能从额外卡组特殊召唤。 ①：只在这张卡在场上表侧表示存在才有1次在自己主要阶段才能发动。从卡组把最多2只「毛绒动物·鼠」特殊召唤。'),
(87246309, 'Fluffal Octopus', '毛绒动物·章鱼', 'ファーニマル・オクト', 'Effect Monster', 'Fairy', 'WATER', 1, 800, 800, '「毛绒动物·章鱼」的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功时，以自己墓地1只「毛绒动物」怪兽或者「锋利小鬼」怪兽为对象才能发动。那只怪兽加入手卡。 ②：这张卡成为「魔玩具」融合怪兽的融合召唤的素材送去墓地的场合，以除外的最多2只自己怪兽为对象才能发动。那些怪兽回到墓地。'),
(65331686, 'Fluffal Owl', '绒毛动物・猫头鹰', 'ファーニマル・オウル', 'Effect Monster', 'Fairy', 'EARTH', 2, 1000, 1000, '「毛绒动物·猫头鹰」的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡从手卡的召唤·特殊召唤成功时才能发动。从卡组把1张「融合」加入手卡。 ②：支付500基本分才能发动。从自己的手卡·场上把「魔玩具」融合怪兽决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(13241004, 'Fluffal Penguin', '绒毛动物・企鹅', 'ファーニマル・ペンギン', 'Effect Monster', 'Fairy', 'WATER', 4, 1600, 1100, '这个卡名的②的效果1回合只能使用1次。 ①：只在这张卡在场上表侧表示存在才有1次，自己主要阶段才能发动。从手卡把「毛绒动物·企鹅」以外的1只「毛绒动物」怪兽特殊召唤。 ②：这张卡成为「魔玩具」融合怪兽的融合召唤的素材送去墓地的场合才能发动。自己从卡组抽2张，那之后选1张手卡丢弃。'),
(38124994, 'Fluffal Rabbit', '毛绒动物·兔子', 'ファーニマル・ラビット', 'Effect Monster', 'Fairy', 'EARTH', 1, 300, 1200, '「毛绒动物·兔子」的效果1回合只能使用1次。 ①：这张卡成为融合召唤的素材送去墓地的场合，以自己墓地1只「锋利小鬼·剪刀」或者1只「毛绒动物·兔子」以外的「毛绒动物」怪兽为对象才能发动。那只怪兽加入手卡。'),
(98280324, 'Fluffal Sheep', '绒毛动物・羊', 'ファーニマル・シープ', 'Effect Monster', 'Fairy', 'EARTH', 2, 400, 800, '「毛绒动物·绵羊」的②的效果1回合只能使用1次。 ①：自己场上有「毛绒动物·绵羊」以外的「毛绒动物」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：让这张卡以外的自己场上1只「毛绒动物」怪兽回到持有者手卡才能发动。从自己的手卡·墓地选1只「锋利小鬼」怪兽特殊召唤。'),
(72413000, 'Fluffal Wings', '绒毛动物・翼', 'ファーニマル・ウィング', 'Effect Monster', 'Fairy', 'LIGHT', 1, 100, 100, '「毛绒动物之翼」的效果1回合只能使用1次。 ①：自己场上有「玩具罐」存在的场合，把墓地的这张卡除外，以自己墓地1只「毛绒动物」怪兽为对象才能发动。那只怪兽除外，自己从卡组抽1张。那之后，以下效果可以适用。 ●选自己场上1张「玩具罐」送去墓地，自己从卡组抽1张。'),
(101303087, 'Flux Ochsenfeld', NULL, NULL, 'Fusion Monster', 'Rock', 'EARTH', 7, 2600, 2000, NULL),
(11954712, 'Flyfang', '飞牙鲛', 'フライファング', 'Effect Monster', 'Fish', 'WIND', 3, 1600, 300, '这张卡向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。这张卡给与对方基本分战斗伤害的战斗阶段结束时，这张卡直到下次的自己的准备阶段时从游戏中除外。'),
(80978111, 'Flying "C"', '飞翔的G', '飛翔するG', 'Effect Monster', 'Insect', 'EARTH', 3, 700, 700, '对方对怪兽的召唤·特殊召唤成功时，这张卡可以从手卡往对方场上表侧守备表示特殊召唤。只要这张卡在场上表侧表示存在，这张卡的控制者不能超量召唤。'),
(66765023, 'Flying Elephant', '飞行象', '飛行エレファント', 'Effect Monster', 'Beast', 'WIND', 4, 1850, 1300, '①：这张卡在对方回合只有1次不会被对方的效果破坏。 ②：这张卡的①的效果适用的对方回合的结束阶段发动。下次的自己回合中，以下适用。 ●这张卡直接攻击给与对方战斗伤害时，自己决斗胜利。'),
(31987274, 'Flying Fish', '飞鱼', 'フライング・フィッシュ', 'Normal Monster', 'Fish', 'WIND', 4, 800, 500, '据说谁看见它在空中飞翔的姿态，就能实现三个愿望。');